entries[207219] = { ["name"] = "Follower: The Monkey King", ["text"] = "Instant\nThe Monkey King was the trusted companion of Shaohao, emperor of all Pandaria. He is mischievous, cunning, and knows untold secrets about Pandaria's past." }
entries[207220] = { ["name"] = "Follower: Angus Ironfist", ["text"] = "Instant\nAngus Ironfist was born into this world with a desire to fight. He loves going toe-to-toe with any rival, and can best them with a combination of martial combat, grapples, wrestling, and well-timed punches and kicks." }
