entries[207222] = { ["name"] = "Follower: Hiro", ["text"] = "Instant\nHiro has wandered the world for many years, ambling aimlessly from one tavern to another in search of the next drink. Don't be fooled by his unkempt appearance - not only does he have a heart of gold, but the more drinks he's had, the better he fights." }
entries[207223] = { ["name"] = "Follower: Sylara Steelsong", ["text"] = "Instant\nSylara Shadowheart is a mysterious wanderer who rarely speaks about her past. One thing is clear - nothing makes her angrier than injustice. Anyone who crosses her will get a taste of her twin blades." }
