entries[207225] = { ["name"] = "Follower: Aegira", ["text"] = "Instant\nAegira is a vrykul brewmaster, favored by Odyn himself. Her brews are legendary. Little do others know, her brawling skills are formidable. She grew up on the battlefield, and is still undefeated by all who challenge her." }
