entries[207235] = { ["name"] = "Follower: Celestos", ["text"] = "Instant\nConsular Celestos is one of the most ancient and venerable elementals within Skywall.\n\nDuring the reign of Al'Akir, Celestos was a chief advisor and tactician during many of the Windlord's campaigns." }
entries[207236] = { ["name"] = "Follower: Nobundo", ["text"] = "Instant\nA former paladin, Farseer Noundo was the first of his people to become a shaman and learn the way of the elements.\n\nHe is one of the wisest and most powerful shaman in the Earthen Ring, and the former leader of the order." }
entries[207237] = { ["name"] = "Follower: Rehgar Earthfury", ["text"] = "Instant\nRehgar Earthfury is a powerful elemental shaman and former gladiator who has mastered the ways of combat.0[source value] There are few members of the Earthen Ring who can match Rehgar's experience and prowess on the battlefield.", ["unresolvedValues"] = true }
entries[207238] = { ["name"] = "Follower: Scaldius", ["text"] = "Instant\nFormerly a lieutenant of Ragnaros, Baron Scaldius now serves Firelord Smolderon with unwaivering loyalty.0[source value] With the power and fury of the Firelands at his command, Baron Scaldius will incinerate any and all foes that cross his path.", ["unresolvedValues"] = true }
entries[207239] = { ["name"] = "Follower: Avalanchion", ["text"] = "Instant\nAmong the great Stone Lords of Deepholm, Avalanchion is known for being virtually indestructible.0[source value] Avalanchion easily ignores mortal sensations such as fear and pain and will fulfill his master's commands with unyielding focus.", ["unresolvedValues"] = true }
entries[207240] = { ["name"] = "Follower: Muln Earthfury", ["text"] = "Instant\nA former leader of the Earthen Ring, Muln Earthfury is one of the greatest shaman of his generation.0[source value] His imposing presence on the battlefield and his mastery of the 'old ways' of shamanism make him a valuable ally.", ["unresolvedValues"] = true }
